<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sayfalar</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:13px;border-bottom:1px solid #edf0ed}.btn{background:#176b50;color:white;padding:10px 14px;border-radius:8px;text-decoration:none}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1>İçerik sayfaları</h1><form method="get" action="/admin/pages" style="max-width:320px;margin:16px 0"><label for="pagesLanguage">İçerik dili</label><select id="pagesLanguage" name="lang" onchange="this.form.submit()" style="padding:10px;border:1px solid #dfe6e0;border-radius:8px"><?php foreach($languages as $language): ?><option value="<?= e($language["code"]) ?>" <?= $language["code"]===$locale?"selected":"" ?>><?= e($language["name"]) ?> (<?= e($language["code"]) ?>)</option><?php endforeach; ?></select><noscript><button type="submit">Dili seç</button></noscript></form><p><a class="btn" href="/admin/pages/new?lang=<?= e(rawurlencode($locale)) ?>">Yeni sayfa</a></p><section class="panel"><table><thead><tr><th>Başlık</th><th>URL</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($pages as $page): ?><tr><td><?= e($page['title']) ?></td><td>/page/<?= e($page['slug']) ?></td><td><?= e($page['status']) ?></td><td><a href="/admin/pages/<?= (int)$page['id'] ?>?lang=<?= e(rawurlencode($locale)) ?>">Düzenle</a></td></tr><?php endforeach; ?><?php if(!$pages): ?><tr><td colspan="4">Henüz sayfa oluşturulmamış.</td></tr><?php endif; ?></tbody></table></section></main></body></html>